er:\n    check: false\n    timeout: 3000\n    retries: 1\n\n# 接口文档：网关统一提供 Swagger UI，按服务聚合\nspringdoc:\n  swagger-ui:\n    path: /docs\n    urls:\n      - name: 用户服务\n        url: /docs/user/v3/api-docs\n      - name: 订单服务\n        url: /docs/order/v3/api-docs\n\n# Sa-Token 无需登录的接口路径列表\nsatoken:\n  permit:\n    paths:\n      - /user/pc/auth/login\n      - /user/pc/auth/register\n      - /user/app/auth/login\n      - /user/app/auth/register\n      # 接口文档（仅 dev/test 放行；生产配置不放行）\n      - /docs\n      - /docs/**\n      - /swagger-ui/**\n      - /v3/api-docs/**\n      - /webjars/**\n  # 接口权限规则存放在 sys_api_resource 表（path/method -> 权限编码），网关启动后通过 Dubbo 加载并定时刷新\n  api-permissions:\n    # 白名单刷新间隔（毫秒），默认 10 秒；修改白名单后最多等待一个间隔生效\n    whitelist-refresh-ms: 10000\n    # 鉴权规则刷新间隔（毫秒），默认 60 秒；权限管理页修改后最多等待一个间隔生效\n    refresh-interval-ms: 60000\n    # 失败即关闭：鉴权规则加载失败（列表为空）时是否拒绝所有非白名单请求。\n    # 生产环境建议 true；开发环境 false 便于排障。\n    fail-closed: true','ecbc49ce96ec5cd853ab7b6c294fc64f','2026-10-24 02:34:24','2026-10-26 14:43:38','nacos','192.168.65.1','','test','gateway-service dev配置',NULL,NULL,'yaml',NULL,''),(39,'order-service-test.yml','DEFAULT_GROUP','# ============================================================\n# order-service 专属配置\n# dataId : order-service-dev.yml\n# group  : DEFAULT_GROUP\n# 命名空间: public\n# 注意：修改端口后需同步调整 docker-compose.yml 中 order-service 的 healthcheck。\n# ============================================================\nserver:\n  port: 8100\n\n# Actuator 使用独立管理端口 8102，仅容器内网络可达\nmanagement:\n  server:\n    port: 8102\n  metrics:\n    tags:\n      application: order-service\n\ndubbo:\n  application:\n    name: dubbo-order-service\n  json-framework:\n    prefer: fastjson2  # 指定使用 fastjson2，避免加载缺少依赖的 FastJson/Gson/Jackson 实现\n  protocol:\n    name: tri\n    port: 20881\n    # Dubbo 注册/绑定的 IP；本地开发按需指定自己电脑 IP，容器环境由 DUBBO_HOST 注入服务名\n    host: ${DUBBO_HOST:127.0.0.1}\n\n# 订单表数据源（与 user-service 共用 ping 库）\nspring:\n  flyway:\n    enabled: true\n    # 每个服务独立的历史表，避免共用同一 schema 时互相锁定/误判\n    table: flyway_schema_history_order\n    # 已存在的库（有表无历史表）以 0 为基线，随后执行 V1（V1 幂等）\n    baseline-on-migrate: true\n    baseline-version: 0\n    locations: classpath:db/migration\n    # 禁止 clean，防止误删生产库\n    clean-disabled: true\n  datasource:\n    url: jdbc:mysql://${MYSQL_HOST:localhost}:${MYSQL_PORT:3306}/${MYSQL_DATABASE:ping}?useUnicode=true&characterEncoding=utf-8&serverTimezone=Asia/Shanghai&useSSL=false&allowPublicKeyRetrieval=true\n    username: ${MYSQL_USERNAME:root}\n    password: ${MYSQL_PASSWORD:123456}\n    driver-class-name: com.mysql.cj.jdbc.Driver\n\n# 接口文档：生成 OpenAPI JSON（/v3/api-docs）；UI 由网关聚合提供\nspringdoc:\n  api-docs:\n    enabled: true\n  # 服务自身不暴露 UI，统一走网关\n  swagger-ui:\n    enabled: false\n  # Swagger UI 从网关访问，"Try it out" 的基地址必须显式声明，\n  # 否则 springdoc 会填成容器内网 IP（如 http://172.27.0.5:8099）。\n  open-api:\n    servers:\n      - url: ${PUBLIC_BASE_URL:http://localhost:9999}\n        description: 网关\n\n# MyBatis-Plus 配置\nmybatis-plus:\n  mapper-locations: classpath*:mapper/*.xml\n  configuration:\n    map-underscore-to-camel-case: true\n    log-impl: org.apache.ibatis.logging.stdout.StdOutImpl\n  global-config:\n    db-config:\n      id-type: auto\n','b64dd72ba7e934c7e1b002ac06379b58','2026-10-24 02:34:24','2026-10-26 14:50:43','nacos','192.168.65.1','','test','order-service dev配置',NULL,NULL,'yaml',NULL,''),(40,'user-service-prod.yml','DEFAULT_GROUP','# ============================================================\n# user-service 专属配置\n# dataId : user-service-dev.yml\n# group  : DEFAULT_GROUP\n# 命名空间: public\n# 注意：修改端口后需同步调整 docker-compose.yml 中 user-service 的 healthcheck。\n# ============================================================\nserver:\n  port: 8099\n\nspring:\n  flyway:\n    enabled: true\n    # 每个服务独立的历史表，避免共用同一 schema 时互相锁定/误判\n    table: flyway_schema_history_user\n    # 已存在的库（有表无历史表）以 0 为基线，随后执行 V1（V1 幂等）\n    baseline-on-migrate: true\n    baseline-version: 0\n    locations: classpath:db/migration\n    # 禁止 clean，防止误删生产库\n    clean-disabled: true\n  datasource:\n    url: jdbc:mysql://${MYSQL_HOST:localhost}:${MYSQL_PORT:3306}/${MYSQL_DATABASE:ping}?useUnicode=true&characterEncoding=utf-8&serverTimezone=Asia/Shanghai&useSSL=false&allowPublicKeyRetrieval=true\n    username: ${MYSQL_USERNAME:root}\n    password: ${MYSQL_PASSWORD:123456}\n    driver-class-name: com.mysql.cj.jdbc.Driver\n\nmanagement:\n  server:\n    port: 8101\n  metrics:\n    tags:\n      application: user-service\n\ndubbo:\n  application:\n    name: dubbo-user-service\n  protocol:\n    name: tri\n    port: 20880\n    # Dubbo 注册/绑定的 IP；不指定时可能选中 VPN/TUN 网卡，本地开发按需指定自己电脑 IP，容器环境由 DUBBO_HOST 注入服务名\n    host: ${DUBBO_HOST:127.0.0.1}\n  scan:\n    base-packages: com.ping.user.pc.service,com.ping.user.app.service\n\n# 登录安全 / 密码策略 / 验证码\nping:\n  security:\n    # 是否开放自助注册\n    registration-enabled: false\n    # 自助注册用户的默认角色（最小权限）\n    default-role-code: guest\n    login:\n      max-attempts: 5\n      lock-minutes: 15\n    password:\n      min-length: 8\n      max-length: 64\n      # 大写/小写/数字/特殊字符至少满足几类\n      require-categories: 3\n    captcha:\n      # 开启后登录必须输入算术验证码\n      enabled: false\n      expire-minutes: 2\n  audit:\n    # 操作日志/登录日志保留天数\n    retention-days: 180\n\n# 生产环境关闭接口文档\nspringdoc:\n  api-docs:\n    enabled: false\n  swagger-ui:\n    enabled: false\n\n# MyBatis-Plus 配置\nmybatis-plus:\n  mapper-locations: classpath*:mapper/*.xml\n  configuration:\n    map-underscore-to-camel-case: true\n    log-impl: org.apache.ibatis.logging.stdout.StdOutImpl\n  global-config:\n    db-config:\n      id-type: auto\n','f00d48b62bad68ea4e0147571297228e','2026-10-24 02:35:21','2026-10-26 14:43:38','nacos','192.168.65.1','','prod','user-service dev环境配置',NULL,NULL,'yaml',NULL,''),(41,'gateway-service-prod.yml','DEFAULT_GROUP','# ============================================================\n# gateway-service 专属配置\n# dataId : gateway-service-dev.yml\n# group  : DEFAULT_GROUP\n# 命名空间: public\n# 注意：修改端口后需同步调整 docker-compose.yml 中 gateway 的 healthcheck。\n# ============================================================\nserver:\n  port: 9999\n\nmanagement:\n  server:\n    port: 8081\n  endpoints:\n    web:\n      exposure:\n        include: health,prometheus,gateway\n  metrics:\n    tags:\n      application: gateway-service\n\n# Gateway 网关配置 (Spring Boot 4.0.6 + Spring Cloud 2025.1.0 / Gateway 5.x)\nspring:\n  cloud:\n    gateway:\n      server:\n        webflux:\n          discovery:\n            locator:\n              enabled: true\n              lower-case-service-id: true\n          routes:\n            # 后台用户接口（/user/pc/**）\n            - id: user-pc\n              uri: lb://user-service\n              order: 1\n              predicates:\n                - Path=/user/pc/**\n            # C 端用户接口（/user/app/**）\n            - id: user-app\n              uri: lb://user-service\n              order: 2\n              predicates:\n                - Path=/user/app/**\n            # 订单服务路由\n            - id: order-service\n              uri: lb://order-service\n              order: 3\n              predicates:\n                - Path=/order/**\n\ndubbo:\n  application:\n    name: dubbo-gateway-service\n  json-framework:\n    prefer: fastjson2\n  consumer:\n    check: false\n    timeout: 3000\n    retries: 1\n\n# 生产环境关闭接口文档\nspringdoc:\n  api-docs:\n    enabled: false\n  swagger-ui:\n    enabled: false\n\n# Sa-Token 无需登录的接口路径列表\nsatoken:\n  permit:\n    paths:\n      - /user/pc/auth/login\n      - /user/pc/auth/register\n      - /user/app/auth/login\n      - /user/app/auth/register\n  # 接口权限规则存放在 sys_api_resource 表（path/method -> 权限编码），网关启动后通过 Dubbo 加载并定时刷新\n  api-permissions:\n    # 白名单刷新间隔（毫秒），默认 10 秒；修改白名单后最多等待一个间隔生效\n    whitelist-refresh-ms: 10000\n    # 鉴权规则刷新间隔（毫秒），默认 60 秒；权限管理页修改后最多等待一个间隔生效\n    refresh-interval-ms: 60000\n    # 失败即关闭：鉴权规则加载失败（列表为空）时是否拒绝所有非白名单请求。\n    # 生产环境建议 true；开发环境 false 便于排障。\n    fail-closed: true','c26fe32ccf1f3497d1da5e8efc6925f7','2026-10-24 02:35:21','2026-10-26 14:43:38','nacos','192.168.65.1','','prod','gateway-service dev配置',NULL,NULL,'yaml',NULL,''),(42,'order-service-prod.yml','DEFAULT_GROUP','# ============================================================\n# order-service 专属配置\n# dataId : order-service-dev.yml\n# group  : DEFAULT_GROUP\n# 命名空间: public\n# 注意：修改端口后需同步调整 docker-compose.yml 中 order-service 的 healthcheck。\n# ============================================================\nserver:\n  port: 8100\n\n# Actuator 使用独立管理端口 8102，仅容器内网络可达\nmanagement:\n  server:\n    port: 8102\n  metrics:\n    tags:\n      application: order-service\n\ndubbo:\n  application:\n    name: dubbo-order-service\n  json-framework:\n    prefer: fastjson2  # 指定使用 fastjson2，避免加载缺少依赖的 FastJson/Gson/Jackson 实现\n  protocol:\n    name: tri\n    port: 20881\n    # Dubbo 注册/绑定的 IP；本地开发按需指定自己电脑 IP，容器环境由 DUBBO_HOST 注入服务名\n    host: ${DUBBO_HOST:127.0.0.1}\n\n# 订单表数据源（与 user-service 共用 ping 库）\nspring:\n  flyway:\n    enabled: true\n    # 每个服务独立的历史表，避免共用同一 schema 时互相锁定/误判\n    table: flyway_schema_history_order\n    # 已存在的库（有表无历史表）以 0 为基线，随后执行 V1（V1 幂等）\n    baseline-on-migrate: true\n    baseline-version: 0\n    locations: classpath:db/migration\n    # 禁止 clean，防止误删生产库\n    clean-disabled: true\n  datasource:\n    url: jdbc:mysql://${MYSQL_HOST:localhost}:${MYSQL_PORT:3306}/${MYSQL_DATABASE:ping}?useUnicode=true&characterEncoding=utf-8&serverTimezone=Asia/Shanghai&useSSL=false&allowPublicKeyRetrieval=true\n    username: ${MYSQL_USERNAME:root}\n    password: ${MYSQL_PASSWORD:123456}\n    driver-class-name: com.mysql.cj.jdbc.Driver\n\n# 生产环境关闭接口文档\nspringdoc:\n  api-docs:\n    enabled: false\n  swagger-ui:\n    enabled: false\n\n# MyBatis-Plus 配置\nmybatis-plus:\n  mapper-locations: classpath*:mapper/*.xml\n  configuration:\n    map-underscore-to-camel-case: true\n    log-impl: org.apache.ibatis.logging.stdout.StdOutImpl\n  global-config:\n    db-config:\n      id-type: auto\n','666303aab866ddb961fd0a99ec619fa6','2026-10-24 02:35:21','2026-10-26 14:43:38','nacos','192.168.65.1','','prod','order-service dev配置',NULL,NULL,'yaml',NULL,'');
