nfig.sh 即可生效\n# ============================================================\nspring:\n  lifecycle:\n    timeout-per-shutdown-phase: 30s\n  data:\n    redis:\n      host: ${REDIS_HOST:localhost}\n      port: ${REDIS_PORT:6379}\n      password: ${REDIS_PASSWORD:}\n      database: 0\n      timeout: 10s\n      lettuce:\n        pool:\n          max-active: 200\n          max-wait: -1ms\n          max-idle: 10\n          min-idle: 0\n\nserver:\n  shutdown: graceful  # 收到 SIGTERM 后优雅关闭，等待活跃请求处理完毕\n\n# Actuator：启用 K8s 存活/就绪探针，Prometheus 指标\nmanagement:\n  endpoints:\n    web:\n      exposure:\n        include: health,prometheus\n  endpoint:\n    health:\n      probes:\n        enabled: true\n  prometheus:\n    metrics:\n      export:\n        enabled: true\n  health:\n    livenessstate:\n      enabled: true\n    readinessstate:\n      enabled: true\n\n# Sa-Token：网关与各业务服务共享 Redis 中的登录态，配置必须完全一致\nsa-token:\n  token-name: ping-token\n  timeout: 86400\n  active-timeout: 1800\n  is-concurrent: true\n  is-share: true\n  token-style: uuid\n  is-log: false\n  token-prefix: Bearer\n\n# Dubbo 公共配置（provider/consumer 各自在服务专属配置里补充）\ndubbo:\n  application:\n    # 同机多服务时 QoS 默认端口 22222 会冲突，统一关闭\n    qos-enable: false\n  registry:\n    address: nacos://${NACOS_HOST:localhost}:${NACOS_PORT:8848}\n    username: ${spring.cloud.nacos.username}\n    password: ${spring.cloud.nacos.password}\n    parameters:\n      namespace: dubbo-dev\n','565813b2265d6397c5e9cb30106bcc8a','2026-10-24 02:28:44','2026-10-24 10:28:45','nacos','192.168.65.1','I','dev','','formal','','{\"src_user\":\"nacos\",\"type\":\"yaml\",\"c_desc\":\"公共配置\"}'),(0,350,'application-test.yml','DEFAULT_GROUP','','# ============================================================\n# 公共配置（所有服务共享）\n# dataId : application-test.yml\n# group  : DEFAULT_GROUP\n# 命名空间: public（配置中心默认）\n#\n# 修改后重新执行 ./start.sh 或 ./scripts/publish-nacos-config.sh 即可生效\n# ============================================================\nspring:\n  lifecycle:\n    tim