${REDIS_PORT:6379}\n      password: ${REDIS_PASSWORD:}\n      database: 0\n      timeout: 10s\n      lettuce:\n        pool:\n          max-active: 200\n          max-wait: -1ms\n          max-idle: 10\n          min-idle: 0\n\nserver:\n  shutdown: graceful  # 收到 SIGTERM 后优雅关闭，等待活跃请求处理完毕\n\n# Actuator：启用 K8s 存活/就绪探针，Prometheus 指标\nmanagement:\n  endpoints:\n    web:\n      exposure:\n        include: health,prometheus\n  endpoint:\n    health:\n      probes:\n        enabled: true\n  prometheus:\n    metrics:\n      export:\n        enabled: true\n  health:\n    livenessstate:\n      enabled: true\n    readinessstate:\n      enabled: true\n\n# Sa-Token：网关与各业务服务共享 Redis 中的登录态，配置必须完全一致\nsa-token:\n  token-name: ping-token\n  timeout: 86400\n  active-timeout: 1800\n  is-concurrent: true\n  is-share: true\n  token-style: uuid\n  is-log: false\n  token-prefix: Bearer\n\n# Dubbo 公共配置（provider/consumer 各自在服务专属配置里补充）\ndubbo:\n  application:\n    # 同机多服务时 QoS 默认端口 22222 会冲突，统一关闭\n    qos-enable: false\n  registry:\n    address: nacos://${NACOS_HOST:localhost}:${NACOS_PORT:8848}\n    username: ${spring.cloud.nacos.username}\n    password: ${spring.cloud.nacos.password}\n    parameters:\n      namespace: dubbo-prod\n','15c03b4905c7fb92985292ac76882def','2026-10-24 02:31:08','2026-10-24 10:31:08','nacos','192.168.65.1','I','prod','','formal','','{\"src_user\":\"nacos\",\"type\":\"yaml\",\"c_desc\":\"prod 公共配置\"}'),(0,352,'user-service-dev.yml','DEFAULT_GROUP','','# ============================================================\n# user-service 专属配置\n# dataId : user-service-dev.yml\n# group  : DEFAULT_GROUP\n# 命名空间: public\n# 注意：修改端口后需同步调整 docker-compose.yml 中 user-service 的 healthcheck。\n# ============================================================\nserver:\n  port: 8099\n\nspring:\n  datasource:\n    url: jdbc:mysql://${MYSQL_HOST:localhost}:${MYSQL_PORT:3306}/${MYSQL_DATABASE:ping}?useUnicode=true&characterEncoding=utf-8&serverTimezone=Asia/Shanghai&useSSL=false&allowPublicKeyRetrieval=true\n    username: ${MYSQL_USERNAME:root}\n    password: ${MYSQL_PASSWORD:123456}\n    driver-class-name: com.mysql.cj.jdbc.Driver\n\nmanagement:\n  server:\n    port: 8101\n  metrics:\n    tags:\n      application: user-service\n\ndubbo:\n  application:\n    name: dubbo-user-service\n  protocol:\n    name: tri\n    port: 20880\n    # Dubbo 注册/绑定的 IP；不指定时可能选中 VPN/TUN 网卡，本地开发按需指定自己电脑 IP，容器环境由 DUBBO_HOST 注入服务名\n    host: ${DUBBO_HOST:127.0.0.1}\n  scan:\n    base-packages: com.ping.user.pc.service,com.ping.user.app.service\n\n# 登录安全 / 密码策略 / 验证码\nping:\n  security:\n    # 是否开放自助注册\n    registration-enabled: false\n    # 自助注册用户的默认角色（最小权限）\n    default-role-code: guest\n    login:\n      max-attempts: 5\n      lock-minutes: 15\n    password:\n      min-length: 8\n      max-length: 64\n      # 大写/小写/数字/特殊字符至少满足几类\n      require-categories: 3\n    captcha:\n      # 开启后登录必须输入算术验证码\n      enabled: false\n      expire-minutes: 2\n  audit:\n    # 操作日志/登录日志保留天数\n    retention-days: 180\n\n# MyBatis-Plus 配置\nmybatis-plus:\n  mapper-locations: classpath*:mapper/*.xml\n  configuration:\n    map-underscore-to-camel-case: true\n    log-impl: org.apache.ibatis.logging.stdout.StdOutImpl\n  global-config:\n    db-config:\n      id-type: auto\n','9e8582a1f195f64b9ce34be65b68328f','2026-10-24 02:32:26','2026-10-24 10:32:27','nacos','192.168.65.1','I','dev','','formal','','{\"src_user\":\"nacos\",\"type\":\"yaml\",\"c_desc\":\"user-service dev环境配置\"}'),(0,353,'gateway-service-dev.yml','DEFAULT_GROUP','','# ============================================================\n# gateway-service 专属配置\n# dataId : gateway-service-dev.yml\n# group  : DEFAULT_GROUP\n# 命名空间: public\n# 注意：修改端口后需同步调整 docker-compose.yml 中 gateway 的 healthcheck。\n# ============================================================\nserver:\n  port: 9999\n\nmanagement:\n  server:\n    port: 8081\n  endpoints:\n    web:\n      exposure:\n        include: health,prometheus,gateway\n  metrics:\n    tags:\n      application: gateway-service\n\n# Gateway 网关配置 (Spring Boot 4.0.6 + Spring Cloud 2025.1.0 / Gateway 5.x)\nspring:\n  cloud:\n    gateway:\n      server:\n        webflux:\n          discovery:\n            locator:\n              enabled: true\n              lower-case-service-id: true\n          routes:\n            # 后台用户接口（/user/pc/**）\n            - id: user-pc\n              uri: lb://user-service\n              order: 1\n              predicates:\n                - Path=/user/pc/**\n            # C 端用户接口（/user/app/**）\n            - id: user-app\n              uri: lb://user-service\n              order: 2\n              predicates:\n                - Path=/user/app/**\n            # 订单服务路由\n            - id: order-service\n              uri: lb://order-service\n              order: 3\n              predicates:\n                - Path=/order/**\n\ndubbo:\n  application:\n    name: dubbo-gateway-service\n  json-framework:\n    prefer: fastjson2\n  consumer:\n    check: false\n    timeout: 3000\n    retries: 1\n\n# Sa-Token 无需登录的接口路径列表\nsatoken:\n  permit:\n    paths:\n      - /user/pc/auth/login\n      - /user/pc/auth/register\n      - /user/app/auth/login\n      - /user/app/auth/register\n  # 接口权限规则存放在 sys_api_resource 表（path/method -> 权限编码），网关启动后通过 Dubbo 加载并定时刷新\n  api-permissions:\n    # 白名单刷新间隔（毫秒），默认 10 秒；修改白名单后最多等待一个间隔生效\n    whitelist-refresh-ms: 10000\n    # 鉴权规则刷新间隔（毫秒），默认 60 秒；权限管理页修改后最多等待一个间隔生效\n    refresh-interval-ms: 60000\n    # 失败即关闭：鉴权规则加载失败（列表为空）时是否拒绝所有非白名单请求。\n    # 生产环境建议 true；开发环境 false 便于排障。\n    fail-closed: true','bb0476384f605203abb425bb62f23093','2026-10-24 02:33:09','2026-10-24 10:33:10','nacos','192.168.65.1','I','dev','','formal','','{\"src_user\":\"nacos\",\"type\":\"yaml\",\"c_desc\":\"gateway-service dev配置\"}'),(0,354,'order-service-dev.yml','DEFAULT_GROUP','','# ============================================================\n# order-service 专属配置\n# dataId : order-service-dev.yml\n# group  : DEFAULT_GROUP\n# 命名空间: public\n# 注意：修改端口后需同步调整 docker-compose.yml 中 order-service 的 healthcheck。\n# ============================================================\nserver:\n  port: 8100\n\n# Actuator 使用独立管理端口 8102，仅容器内网络可达\nmanagement:\n  server:\n    port: 8102\n  metrics:\n    tags:\n      application: order-service\n\ndubbo:\n  application:\n    name: dubbo-order-service\n  json-framework:\n    prefer: fastjson2  # 指定使用 fastjson2，避免加载缺少依赖的 FastJson/Gson/Jackson 实现\n  protocol:\n    name: tri\n    port: 20881\n    # Dubbo 注册/绑定的 IP；本地开发按需指定自己电脑 IP，容器环境由 DUBBO_HOST 注入服务名\n    host: ${DUBBO_HOST:127.0.0.1}','c8bfdd67698515296d348f1464152b0a','2026-10-24 02:33:49','2026-10-24 10:33:49','nacos','192.168.65.1','I','dev','','formal','','{\"src_user\":\"nacos\",\"type\":\"yaml\",\"c_desc\":\"order-service dev配置\"}'),(0,355,'user-service-test.yml','DEFAULT_GROUP','','# ============================================================\n# user-service 专属配置\n# dataId : user-service-dev.yml\n# group  : DEFAULT_GROUP\n# 命名空间: public\n# 注意：修改端口后需同步调整 docker-compose.yml 中 user-service 的 healthcheck。\n# ============================================================\nserver:\n  port: 8099\n\nspring:\n  datasource:\n    url: jdbc:mysql://${MYSQL_HOST:localhost}:${MYSQL_PORT:3306}/${MYSQL_DATABASE:ping}?useUnicode=true&characterEncoding=utf-8&serverTimezone=Asia/Shanghai&useSSL=false&allowPublicKeyRetrieval=true\n    username: ${MYSQL_USERNAME:root}\n    password: ${MYSQL_PASSWORD:123456}\n    driver-class-name: com.mysql.cj.jdbc.Driver\n\nmanagement:\n  server:\n    port: 8101\n  metrics:\n    tags:\n      application: user-service\n\ndubbo:\n  application:\n    name: dubbo-user-service\n  protocol:\n    name: tri\n    port: 20880\n    # Dubbo 注册/绑定的 IP；不指定时可能选中 VPN/TUN 网卡，本地开发按需指定自己电脑 IP，容器环境由 DUBBO_HOST 注入服务名\n    host: ${DUBBO_HOST:127.0.0.1}\n  scan:\n    base-packages: com.ping.user.pc.service,com.ping.user.app.service\n\n# 登录安全 / 密码策略 / 验证码\nping:\n  security:\n    # 是否开放自助注册\n    registration-enabled: false\n    # 自助注册用户的默认角色（最小权限）\n    default-role-code: guest\n    login:\n      max-attempts: 5\n      lock-minutes: 15\n    password:\n      min-length: 8\n      max-length: 64\n      # 大写/小写/数字/特殊字符至少满足几类\n      require-categories: 3\n    captcha:\n      # 开启后登录必须输入算术验证码\n      enabled: false\n      expire-minutes: 2\n  audit:\n    # 操作日志/登录日志保留天数\n    retention-days: 180\n\n# MyBatis-Plus 配置\nmybatis-plus:\n  mapper-locations: classpath*:mapper/*.xml\n  configuration:\n    map-underscore-to-camel-case: true\n    log-impl: org.apache.ibatis.logging.stdout.StdOutImpl\n  global-config:\n    db-config:\n      id-type: auto\n','9e8582a1f195f64b9ce34be65b68328f','2026-10-24 02:34:24','2026-10-24 10:34:24','nacos','192.168.65.1','I','test','','formal','','{\"src_user\":\"nacos\",\"type\":\"yaml\",\"c_desc\":\"user-service dev环境配置\"}'),(0,356,'gateway-service-test.yml','DEFAULT_GROUP','','# ============================================================\n# gateway-service 专属配置\n# dataId : gateway-service-dev.yml\n# group  : DEFAULT_GROUP\n# 命名空间: public\n# 注意：修改端口后需同步调整 docker-compose.yml 中 gateway 的 healthcheck。\n# ============================================================\nserver:\n  port: 9999\n\nmanagement:\n  server:\n    port: 8081\n  endpoints:\n    web:\n      exposure:\n        include: health,prometheus,gateway\n  metrics:\n    tags:\n      application: gateway-service\n\n# Gateway 网关配置 (Spring Boot 4.0.6 + Spring Cloud 2025.1.0 / Gateway 5.x)\nspring:\n  cloud:\n    gateway:\n      server:\n        webflux:\n          discovery:\n            locator:\n              enabled: true\n              lower-case-service-id: true\n          routes:\n            # 后台用户接口（/user/pc/**）\n            - id: user-pc\n              uri: lb://user-service\n              order: 1\n              predicates:\n                - Path=/user/pc/**\n            # C 端用户接口（/user/app/**）\n            - id: user-app\n              uri: lb://user-service\n              order: 2\n              predicates:\n                - Path=/user/app/**\n            # 订单服务路由\n            - id: order-service\n              uri: lb://order-service\n              order: 3\n              predicates:\n                - Path=/order/**\n\ndubbo:\n  application:\n    name: dubbo-gateway-service\n  json-framework:\n    prefer: fastjson2\n  consumer:\n    check: false\n    timeout: 3000\n    retries: 1\n\n# Sa-Token 无需登录的接口路径列表\nsatoken:\n  permit:\n    paths:\n      - /user/pc/auth/login\n      - /user/pc/auth/register\n      - /user/app/auth/login\n      - /user/app/auth/register\n  # 接口权限规则存放在 sys_api_resource 表（path/method -> 权限编码），网关启动后通过 Dubbo 加载并定时刷新\n  api-permissions:\n    # 白名单刷新间隔（毫秒），默认 10 秒；修改白名单后最多等待一个间隔生效\n    whitelist-refresh-ms: 10000\n    # 鉴权规则刷新间隔（毫秒），默认 60 秒；权限管理页修改后最多等待一个间隔生效\n    refresh-interval-ms: 60000\n    # 失败即关闭：鉴权规则加载失败（列表为空）时是否拒绝所有非白名单请求。\n    # 生产环境建议 true；开发环境 false 便于排障。\n    fail-closed: true','bb0476384f605203abb425bb62f23093','2026-10-24 02:34:24','2026-10-24 10:34:24','nacos','192.168.65.1','I','test','','formal','','{\"src_user\":\"nacos\",\"type\":\"yaml\",\"c_desc\":\"gateway-service dev配置\"}'),(0,357,'order-service-test.yml','DEFAULT_GROUP','','# ============================================================\n# order-service 专属配置\n# dataId : order-service-dev.yml\n# group  : DEFAULT_GROUP\n# 命名空间: public\n# 注意：修改端口后需同步调整 docker-compose.yml 中 order-service 的 healthcheck。\n# ============================================================\nserver:\n  port: 8100\n\n# Actuator 使用独立管理端口 8102，仅容器内网络可达\nmanagement:\n  server:\n    port: 8102\n  metrics:\n    tags:\n      application: order-service\n\ndubbo:\n  application:\n    name: dubbo-order-service\n  json-framework:\n    prefer: fastjson2  # 指定使用 fastjson2，避免加载缺少依赖的 FastJson/Gson/Jackson 实现\n  protocol:\n    name: tri\n    port: 20881\n    # Dubbo 注册/绑定的 IP；本地开发按需指定自己电脑 IP，容器环境由 DUBBO_HOST 注入服务名\n    host: ${DUBBO_HOST:127.0.0.1}','c8bfdd67698515296d348f1464152b0a','2026-10-24 02:34:24','2026-10-24 10:34:24','nacos','192.168.65.1','I','test','','formal','','{\"src_user\":\"nacos\",\"type\":\"yaml\",\"c_desc\":\"order-service dev配置\"}'),(0,358,'user-service-prod.yml','DEFAULT_GROUP','','# ============================================================\n# user-service 专属配置\n# dataId : user-service-dev.yml\n# group  : DEFAULT_GROUP\n# 命名空间: public\n# 注意：修改端口后需同步调整 docker-compose.yml 中 user-service 的 healthcheck。\n# ============================================================\nserver:\n  port: 8099\n\nspring:\n  datasource:\n    url: jdbc:mysql://${MYSQL_HOST:localhost}:${MYSQL_PORT:3306}/${MYSQL_DATABASE:ping}?useUnicode=true&characterEncoding=utf-8&serverTimezone=Asia/Shanghai&useSSL=false&allowPublicKeyRetrieval=true\n    username: ${MYSQL_USERNAME:root}\n    password: ${MYSQL_PASSWORD:123456}\n    driver-class-name: com.mysql.cj.jdbc.Driver\n\nmanagement:\n  server:\n    port: 8101\n  metrics:\n    tags:\n      application: user-service\n\ndubbo:\n  application:\n    name: dubbo-user-service\n  protocol:\n    name: tri\n    port: 20880\n    # Dubbo 注册/绑定的 IP；不指定时可能选中 VPN/TUN 网卡，本地开发按需指定自己电脑 IP，容器环境由 DUBBO_HOST 注入服务名\n    host: ${DUBBO_HOST:127.0.0.1}\n  scan:\n    base-packages: com.ping.user.pc.service,com.ping.user.app.service\n\n# 登录安全 / 密码策略 / 验证码\nping:\n  security:\n    # 是否开放自助注册\n    registration-enabled: false\n    # 自助注册用户的默认角色（最小权限）\n    default-role-code: guest\n    login:\n      max-attempts: 5\n      lock-minutes: 15\n    password:\n      min-length: 8\n      max-length: 64\n      # 大写/小写/数字/特殊字符至少满足几类\n      require-categories: 3\n    captcha:\n      # 开启后登录必须输入算术验证码\n      enabled: false\n      expire-minutes: 2\n  audit:\n    # 操作日志/登录日志保留天数\n    retention-days: 180\n\n# MyBatis-Plus 配置\nmybatis-plus:\n  mapper-locations: classpath*:mapper/*.xml\n  configuration:\n    map-underscore-to-camel-case: true\n    log-impl: org.apache.ibatis.logging.stdout.StdOutImpl\n  global-config:\n    db-config:\n      id-type: auto\n','9e8582a1f195f64b9ce34be65b68328f','2026-10-24 02:35:20','2026-10-24 10:35:21','nacos','192.168.65.1','I','prod','','formal','','{\"src_user\":\"nacos\",\"type\":\"yaml\",\"c_desc\":\"user-service dev环境配置\"}'),(0,359,'gateway-service-prod.yml','DEFAULT_GROUP','','# ============================================================\n# gateway-service 专属配置\n# dataId : gateway-service-dev.yml\n# group  : DEFAULT_GROUP\n# 命名空间: public\n# 注意：修改端口后需同步调整 docker-compose.yml 中 gateway 的 healthcheck。\n# ============================================================\nserver:\n  port: 9999\n\nmanagement:\n  server:\n    port: 8081\n  endpoints:\n    web:\n      exposure:\n        include: health,prometheus,gateway\n  metrics:\n    tags:\n      application: gateway-service\n\n# Gateway 网关配置 (Spring Boot 4.0.6 + Spring Cloud 2025.1.0 / Gateway 5.x)\nspring:\n  cloud:\n    gateway:\n      server:\n        webflux:\n          discovery:\n            locator:\n              enabled: true\n              lower-case-service-id: true\n          routes:\n            # 后台用户接口（/user/pc/**）\n            - id: user-pc\n              uri: lb://user-service\n              order: 1\n              predicates:\n                - Path=/user/pc/**\n            # C 端用户接口（/user/app/**）\n            - id: user-app\n              uri: lb://user-service\n              order: 2\n              predicates:\n                - Path=/user/app/**\n            # 订单服务路由\n            - id: order-service\n              uri: lb://order-service\n              order: 3\n              predicates:\n                - Path=/order/**\n\ndubbo:\n  application:\n    name: dubbo-gateway-service\n  json-framework:\n    prefer: fastjson2\n  consumer:\n    check: false\n    timeout: 3000\n    retries: 1\n\n# Sa-Token 无需登录的接口路径列表\nsatoken:\n  permit:\n    paths:\n      - /user/pc/auth/login\n      - /user/pc/auth/register\n      - /user/app/auth/login\n      - /user/app/auth/register\n  # 接口权限规则存放在 sys_api_resource 表（path/method -> 权限编码），网关启动后通过 Dubbo 加载并定时刷新\n  api-permissions:\n    # 白名单刷新间隔（毫秒），默认 10 秒；修改白名单后最多等待一个间隔生效\n    whitelist-refresh-ms: 10000\n    # 鉴权规则刷新间隔（毫秒），默认 60 秒；权限管理页修改后最多等待一个间隔生效\n    refresh-interval-ms: 60000\n    # 失败即关闭：鉴权规则加载失败（列表为空）时是否拒绝所有非白名单请求。\n    # 生产环境建议 true；开发环境 false 便于排障。\n    fail-closed: true','bb0476384f605203abb425bb62f23093','2026-10-24 02:35:20','2026-10-24 10:35:21','nacos','192.168.65.1','I','prod','','formal','','{\"src_user\":\"nacos\",\"type\":\"yaml\",\"c_desc\":\"gateway-service dev配置\"}'),(0,360,'order-service-prod.yml','DEFAULT_GROUP','','# ============================================================\n# order-service 专属配置\n# dataId : order-service-dev.yml\n# group  : DEFAULT_GROUP\n# 命名空间: public\n# 注意：修改端口后需同步调整 docker-compose.yml 中 order-service 的 healthcheck。\n# ============================================================\nserver:\n  port: 8100\n\n# Actuator 使用独立管理端口 8102，仅容器内网络可达\nmanagement:\n  server:\n    port: 8102\n  metrics:\n    tags:\n      application: order-service\n\ndubbo:\n  application:\n    name: dubbo-order-service\n  json-framework:\n    prefer: fastjson2  # 指定使用 fastjson2，避免加载缺少依赖的 FastJson/Gson/Jackson 实现\n  protocol:\n    name: tri\n    port: 20881\n    # Dubbo 注册/绑定的 IP；本地开发按需指定自己电脑 IP，容器环境由 DUBBO_HOST 注入服务名\n    host: ${DUBBO_HOST:127.0.0.1}','c8bfdd67698515296d348f1464152b0a','2026-10-24 02:35:20','2026-10-24 10:35:21','nacos','192.168.65.1','I','prod','','formal','','{\"src_user\":\"nacos\",\"type\":\"yaml\",\"c_desc\":\"order-service dev配置\"}'),(30,361,'com.ping.user.client.spi.AppUserDubboClient:::provider:dubbo-user-service','dubbo','','{\"annotations\":[],\"canonicalName\":\"com.ping.user.client.spi.AppUserDubboClient\",\"codeSource\":\"file:/Users/humdeef/wk/ping-permission/ping-user/user-client/target/classes/\",\"methods\":[{\"annotations\":[],\"name\":\"getNicknameById\",\"parameterTypes\":[\"java.lang.Long\"],\"parameters\":[],\"returnType\":\"java.lang.String\"}],\"parameters\":{\"interface\":\"com.ping.user.client.spi.AppUserDubboClient\",\"application\":\"d